defmodule Jamdb.Oracle.Integration.ReturningTest do
  use ExUnit.Case, async: false

  @moduletag :oracle

  import Ecto.Query

  alias Jamdb.Oracle.Integration
  alias Jamdb.Oracle.Integration.Repo

  defmodule Item do
    use Ecto.Schema

    schema "jamdb_it_returning" do
      field :name, :string
      field :qty, :integer
    end
  end

  setup_all do
    start_supervised!({Repo, Integration.config()})
    Integration.drop_table(Repo, "jamdb_it_returning")

    Repo.query!(
      "CREATE TABLE jamdb_it_returning (id INTEGER GENERATED BY DEFAULT AS IDENTITY " <>
        "PRIMARY KEY, name VARCHAR2(20), qty INTEGER)"
    )

    on_exit(fn ->
      Integration.with_repo(Repo, fn ->
        Integration.drop_table(Repo, "jamdb_it_returning")
      end)
    end)

    :ok
  end

  test "insert, update and delete return several fields" do
    {:ok, item} = Repo.insert(%Item{name: "a", qty: 1}, returning: [:id, :name, :qty])
    assert %Item{id: id, name: "a", qty: 1} = item
    assert is_integer(id)

    {:ok, item} =
      item |> Ecto.Changeset.change(qty: 2) |> Repo.update(returning: [:name, :qty])

    assert %Item{id: ^id, name: "a", qty: 2} = item

    assert {:ok, %Item{name: "a", qty: 2}} = Repo.delete(item, returning: [:name, :qty])
    assert Repo.get(Item, id) == nil
  end

  test "raw queries with out binds keep one list per bind" do
    Repo.insert!(%Item{name: "b", qty: 5})

    assert %{rows: [[_id], [5]]} =
             Repo.query!(
               "UPDATE jamdb_it_returning SET qty = qty WHERE name = 'b' RETURN id, qty INTO :id, :qty",
               [],
               out: [:integer, :integer]
             )
  end

  test "update_all and delete_all with select raise before reaching the database" do
    item = Repo.insert!(%Item{name: "c", qty: 7})
    query = from(i in Item, where: i.id == ^item.id, select: i.qty)

    assert_raise Ecto.QueryError, ~r/:select is not supported in update_all/, fn ->
      Repo.update_all(query, set: [qty: 8])
    end

    assert_raise Ecto.QueryError, ~r/:select is not supported in delete_all/, fn ->
      Repo.delete_all(query)
    end

    assert %Item{qty: 7} = Repo.get!(Item, item.id)
    assert {1, nil} = Repo.update_all(from(i in Item, where: i.id == ^item.id), set: [qty: 8])
    assert %Item{qty: 8} = Repo.get!(Item, item.id)
  end

  test "FOR UPDATE returns every locked row" do
    for n <- 1..3, do: Repo.insert!(%Item{name: "lock", qty: n})
    query = from(i in Item, where: i.name == "lock", order_by: i.qty, select: i.qty)

    assert {:ok, [1, 2, 3]} =
             Repo.transaction(fn -> query |> lock("FOR UPDATE") |> Repo.all() end)

    assert {:ok, [1, 2, 3]} =
             Repo.transaction(fn -> query |> lock("FOR UPDATE SKIP LOCKED") |> Repo.all() end)
  end
end
